        # Validate that the group contains only parentheses characters
        if not group or any(ch not in "()" for ch in group):
            raise ValueError(
                f"Invalid group '{group}': only '(' and ')' characters are allowed"
            )

        current_depth = 0
        max_depth = 0
        balance = 0  # used to check that parentheses are balanced

        for ch in group:
            if ch == "(":
                current_depth += 1
                balance += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ")":
                current_depth -= 1
                balance -= 1
